/**
 * Brings a deleted workspace back during its retention window. No `Actor` can
 * be resolved for a deleted workspace, so the caller is identified by user id
 * and the membership is read directly. A workspace that is not deleted is
 * returned unchanged and nothing is published.
 */
export async function restoreOrganization(
  userId: UserId,
  orgId: OrgId,
): Promise<Organization> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) throw new NotFoundError("Organization", orgId);

  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") {
    throw new NotFoundError("Organization", orgId);
  }

  if (isArchived(org) && isRetentionClosed(org.archivedAt, Date.now())) {
    throw new NotFoundError("Organization", orgId);
  }

  const actor: Actor = { userId, orgId, role: member.role };
  assertCan(actor, "org:restore", orgResource(orgId));

  if (!isArchived(org)) return org;

  const restored = await orgRepo.restoreOrg(orgId);

  await emit("organization.restored", {
    ...envelope(orgId, userId),
    slug: restored.slug,
  });

  return restored;
}

/** True once the retention window measured from `archivedAt` has run out. */
function isRetentionClosed(archivedAt: string | null, now: number): boolean {
  if (archivedAt === null) return false;
  return Date.parse(archivedAt) + RETENTION_MS <= now;
}
